"432 // 书籍词典
 -1 // 组句子结果
 // 静态拼音中文词典，也就是基础中文词典
 STATIC_PINYIN_DICT = 0,
 // 静态基础中英文混输词典，中文键盘用
 STATIC_ENGLISH_DICT = 1,
 // 汉字转拼音的词典，输入时不会用到，本地联系人用
 STATIC_REVERSE_PINYIN_DICT = 2,
 // 静态纯英文词典，英文键盘用
 STATIC_PURE_ENGLISH_DICT = 3,
 // 英文语言模型
 STATIC_ENGLISH_LM_DICT = 4,
 // 标准emoji字典，已废弃
 STANDARD_EMOJI_DICT = 5,
 // 微信内部emoji字典，已废弃
 WECHAT_EMOJI_DICT = 6,
 // 前缀联想词典，前缀树做前缀匹配
 PREFIX_DICT = 7,
 // 联想黑白名单
 ASSO_WB_DICT = 8,
 // 联想词典，KV形式匹配
 ASSO_KV_DICT = 9,
 // 简拼字典,key是全简拼，value是完整拼音列表
 EXPERIMENTAL_JIANPIN_DICT = 10,
 // 姓氏过滤字典，例如单在姓氏里面只能读作shan
 LAST_NAME_SYLLABLE_DICT = 11,
 // 长简拼字典,key是完整拼音，value是中文列表
 LONG_JIANPIN_DICT = 12,
 // 给多音词打分，例如了解，他对于le,jie的得分就很低
 WORD_SYLLABLE_DICT = 13,
 // 五笔基础字典
 STATIC_WUBI_DICT = 14,
 // 二级词典，和STATIC_PINYIN_DICT一样
 LOW_PRIORITY_STATIC_PINYIN_DICT = 15,
 // 二级简拼词典，类似EXPERIMENTAL_JIANPIN_DICT
 LOW_PRIORITY_EXPERIMENTAL_JIANPIN_DICT = 16,
 // 中文->emoji词典，广义的emoji，目前还包含数学符号
 EMOJI_C2E_KV_DICT = 17,
 // emoji->中文词典
 EMOJI_E2C_KV_DICT = 18,
 // 汉字查五笔词典
 REVERSE_WUBI_DICT = 19,
 // 手写语言模型，暂时没有用
 HW_LM_CN_CHAR = 0x40,(64)
 // 手写词典
 HW_DECODER_WORD_MAP = 0x41,(65)
 // 手写模型
 HW_MODEL_BINARY = 0x42,(66)
 // 用户词典相关的起始位置(含)
 USER_RELATED_BEGIN = 0x80,(128)
 // 用户词典
 USER_DICT = 0x80,
 // 本地联系人词典
 LOCAL_CONTACT_DICT = 0x81,(129)
 // 用户的英文词典，硬造的英文词存在这里
 USER_ENGLISH_DICT = 0x82,(130)
 // 用户自造词做联想
 USER_BIGRAM_DICT = 0x83,(131)
 // 用户常用语
 USER_HOT_WORD_DICT = 0x84,(132)
 // 用户词典结束位置(含)
 USER_RELATED_END = 0xff,(255)
 // cell dict的起始位置(含)
 CELL_DICT_BEGIN = 0x100,(256)
 // cell dict大部分是普通的，最后少部分是HOT的，HOT的不会被拼音剪枝
 HOT_CELL_DICT_BEGIN = 0x1C0,(448)
 // cell dict的结束(含)
 CELL_DICT_END = 0x1FF,(511)
 // unknown
 NOT_SPECIFIED_DICT = 0xFFFF,(65535)"
